components.props:
type IconButtonProps = Omit<PrimitiveProps<'button'>, 'as' | 'children'> & {
  name: SymProps['name']
  size?: number
  variant?: 'plain' | 'tinted' | 'round'
  'aria-label': string
}

type SegmentedProps<T extends string> = Omit<PrimitiveProps<'div'>, 'as' | 'onChange' | 'children'> & {
  options: readonly T[]
  value: T
  onChange: (value: T) => void
}

type SheetProps = Omit<PrimitiveProps<'dialog'>, 'as' | 'open' | 'onClose'> & {
  open: boolean
  onClose: () => void
}

type RowProps<T extends ElementType = 'div'> = PrimitiveProps<T> & {
  label?: ReactNode
  /** Second line under `label`, in the secondary colour. Most iOS rows have one. */
  subtitle?: ReactNode
  detail?: ReactNode
  icon?: ReactNode
  chevron?: boolean
}

type WidgetProps = {
  snapshot: WidgetSnapshot
  updatedAt: number
  onOpen: (element: HTMLElement, arg?: string) => void
}
